  async def _poll_dm_status(self, bit, value, retries=100):
    while True:
      status = await self.read_csr(DebugCsrAddr.STATUS)
      if (status[0] & (1 << bit)) == value:
        break
      await ClockCycles(self.dut.io_aclk, 10)
      retries -= 1
