            low=np.iinfo(dtype).min,
            high=np.iinfo(dtype).max+1, size=1, dtype=dtype)
        expected_output = expfunc(dest_data, src_data, scalar, vl, offset)

        if dtype == np.int8:
            dest_buf = 'buf_dest8'
            src_buf = 'buf_src8'
